///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnFileDownReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
} else {
    $c.util.getComponent("dma_fnFileDownReq").set("repIsuSrtCd", "");
    await scwin.fnSearchInit();
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items.length == 1) {
        await scwin.fnSearchCorpCode(items[0].repisusrtcd);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode('');
    }
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_repIsuSrtCd
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function (ipt_repIsuSrtCd) {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_repIsuSrtCd === "") {
        $c.util.getComponent("dma_fnFileDownReq").set("repIsuSrtCd", '');
        const val = ($c.util.getComponent("dma_fnFileDownReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
    } else {
        $c.util.getComponent("dma_fnFileDownReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
        await scwin.fnSearchInit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fnDetailClose();
    $c.util.getComponent("dma_fnFileDownReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_startDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_endDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_startDate').getValue(), $c.util.getComponent('cal_endDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    $c.util.getComponent("dma_fnFileDownReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnFileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnFileDownReq").set("method", "listingForeignCompanyList");
    $c.util.getComponent("dma_fnFileDownReq").set("forward", "irResourceRoomList");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack1
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack1 = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch1 = async function () {
    /* sdd-asis-lifecycle:begin fnSearch1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnFileDownReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnFileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDetailView
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_contnId
 * @returns
 * @hidden N
*/
scwin.fnDetailView = async function (ipt_contnId) {
    /* sdd-asis-lifecycle:begin fnDetailView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("detailContents").setStyle("display", "");
    $c.util.getComponent("dma_fnFileDownReq").set("contnId", ipt_contnId);
    $c.util.getComponent("dma_fnFileDownReq").set("method", "listingForeignCompanyDetail");
    $c.util.getComponent("dma_fnFileDownReq").set("forward", "irResourceRoomDetail");
    await scwin.tx_fnDetailView_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack2
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack2 = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#detailContents").empty().append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDetailClose
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDetailClose = function () {
    /* sdd-asis-lifecycle:begin fnDetailClose — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#detailContents").empty();
    $c.util.getComponent("detailContents").setStyle("display", "none");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd ipt_repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_repIsuSrtCd').setValue(ipt_repIsuSrtCd);
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent('ipt_searchCodeType').setValue("char");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnFileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_resoroomId ipt_attachSeq ipt_attachFileNm
 * @returns
 * @hidden N
*/
scwin.fnFileDown = async function (ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm) {
    /* sdd-asis-lifecycle:begin fnFileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnFileDownReq").set("method", "downloadCorpReportIr");
    $c.util.getComponent("dma_fnFileDownReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_fnFileDownReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_fnFileDownReq").set("attachFileNm", ipt_attachFileNm);
    await scwin.tx_fnFileDown();
    /* sdd-asis-lifecycle:end */
};
